{
  "title": "The Mirror Rescue",
  "gate_token": "BMZcO0FeV0Y1alXD6dJPxQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a crumbling map at the city's edge.",
      "visual_description": "Ruined gates loom ahead, with old royal banners tattered on poles. Mara studies a worn map by fading daylight, while the tin fox sniffs the ground nearby.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver surfaces from a broken window.",
      "visual_description": "Shards of stained glass lie around a frame; the glass diver climbs out, helmet gleaming, coat reflecting the crumbling towers beyond.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning near the cursed tower.",
      "visual_description": "Inside a shadowy courtyard, the oracle lamp's flame eye glows as it speaks, casting long shadows from a twisted spire overhead.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The sleeping tax collector snores on a pile of ledgers.",
      "visual_description": "In a roofless hall, the tax collector dozes with a ledger as a pillow, stamped papers stuck to sleeves, oblivious to the danger outside.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox discovers a hidden passage beneath a collapsed arch.",
      "visual_description": "The small metal fox noses through rubble, its blue eyes glowing, tail winding, as it finds a narrow opening under a stone arch.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara consults the oracle lamp by a magic door.",
      "visual_description": "Before a door carved with shifting runes, Mara holds the lamp high; the flame eye studies the symbols, reflecting in her compass.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through the magic door's mirror surface.",
      "visual_description": "The door's surface ripples like water; the glass diver steps through, helmet catching light, into a corridor of reflections.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin fox scouts ahead and reports to Mara.",
      "visual_description": "The clockwork fox returns to Mara, tapping its paw on her boot, then points with its snout toward an armored patrol rounding a corner.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "The group hides behind old royal banners as patrols march past.",
      "visual_description": "Dusty banners with faded crests hang from a collapsed gallery; Mara, the tin fox, and the glass diver press flat as armored boots echo on stone.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara finds the next location on the map inside a broken tower.",
      "visual_description": "Inside a spiral stairwell with gaping holes, Mara traces a route with her finger, the oracle lamp casting a small circle of light.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector is accidentally awakened by the tin fox.",
      "visual_description": "The tin fox's tail brushes a stamp; the tax collector stirs, blinks at the group, then yawns and goes back to sleep.",
      "characters": ["sleeping_tax_collector", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp reveals a trap in the courtyard ahead.",
      "visual_description": "The lamp's flame turns blue as it illuminates a hidden pit beneath loose cobblestones; Mara signals the others to halt.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Glass diver crosses the pit by walking on mirror shards.",
      "visual_description": "Shards of mirror embedded in the walls reflect the diver's form as he steps lightly across, each shard holding his reflection.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Tin fox leads the way through a crumbling barracks.",
      "visual_description": "Rusty armor racks and broken furniture fill the room; the tin fox weaves between debris, tail ticking like a metronome.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Mara deciphers a wall carving with the oracle lamp's help.",
      "visual_description": "A large stone relief shows a bridge; Mara traces lines while the lamp's eye glows, revealing a hidden route.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver retrieves a key from a submerged chamber.",
      "visual_description": "Under a flooded cellar, the diver swims through a broken window, grabs a rusted key from a stone shelf, and surfaces.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The group unlocks the final gate and rushes across the bridge.",
      "visual_description": "The key turns in a massive lock; the gate groans open, and the group runs onto a long stone bridge over a dark chasm, banners whipping in the wind.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Across the bridge, they look back at the ruined city.",
      "visual_description": "On the far side, the group pauses. The city burns with twilight behind them; the oracle lamp's flame dims as Mara folds the map.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

